-- The cookbook's ingredients, once each, in both languages (lib/ingredientCatalog).
CREATE TABLE "IngredientItem" (
    "id" SERIAL NOT NULL,
    "de" TEXT NOT NULL DEFAULT '',
    "en" TEXT NOT NULL DEFAULT '',
    "aliases" TEXT[] DEFAULT ARRAY[]::TEXT[],
    "keys" TEXT[] DEFAULT ARRAY[]::TEXT[],
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,
    CONSTRAINT "IngredientItem_pkey" PRIMARY KEY ("id")
);
CREATE INDEX "IngredientItem_keys_idx" ON "IngredientItem" USING GIN ("keys");

ALTER TABLE "Ingredient" ADD COLUMN "itemId" INTEGER;
ALTER TABLE "Ingredient" ADD CONSTRAINT "Ingredient_itemId_fkey" FOREIGN KEY ("itemId") REFERENCES "IngredientItem"("id") ON DELETE SET NULL ON UPDATE CASCADE;
CREATE INDEX "Ingredient_itemId_idx" ON "Ingredient"("itemId");

ALTER TABLE "ShoppingItem" ADD COLUMN "itemId" INTEGER;
ALTER TABLE "ShoppingItem" ADD CONSTRAINT "ShoppingItem_itemId_fkey" FOREIGN KEY ("itemId") REFERENCES "IngredientItem"("id") ON DELETE SET NULL ON UPDATE CASCADE;

-- The common ingredients to start with (lib/ingredientNames). Every other
-- one is added the first time a recipe uses it.
;
